/// <summary>
/// find last created record by item rec id
/// </summary>
/// <param name = "_inventTableRefRecId">Rec Id of invent table record</param>
/// <param name = "_forupdate">for update</param>
/// <returns>NDXHK2MGKHistory record</returns>
public static NDXItemNetWeightHistory findLast(RefRecId _inventTableRefRecId, boolean _forupdate = false)
{
    NDXItemNetWeightHistory lNDXItemNetWeightHistory;

    lNDXItemNetWeightHistory.selectForUpdate(_forupdate);

    select firstonly lNDXItemNetWeightHistory order by lNDXItemNetWeightHistory.CreatedDateTime desc
        where lNDXItemNetWeightHistory.InventTableRefRecId == _inventTableRefRecId;

    return lNDXItemNetWeightHistory;
}

/// <summary>
/// record exists
/// </summary>
/// <param name = "_dateTimeChanged">datetime</param>
/// <param name = "_recId">recid</param>
/// <param name = "_update">update</param>
/// <returns>true or false</returns>
static boolean exists(utcdatetime _dateTimeChanged, RecId _recId, boolean _update = false)
{
    NDXItemNetWeightHistory  lNDXItemNetWeightHistory = NDXItemNetWeightHistory::findLast(_recId, _update);
    return lNDXItemNetWeightHistory.RecId;
}

/// <summary>
/// Create History by InventTable
/// </summary>
/// <param name = "_inventTable">Invent table record</param>
/// <param name = "_orig">Invent table record befor change</param>
public static void createByInventTable(InventTable _inventTable, InventTable _orig = null)
{
    NDXItemNetWeightHistory lNDXItemNetWeightHistory = NDXItemNetWeightHistory::findLast(_inventTable.RecId);
    NDXItemNetWeightHistory newHistoryRecord;

    if(lNDXItemNetWeightHistory.NetWeightTo != _inventTable.NetWeight)
    {
        newHistoryRecord.InventTableRefRecId = _inventTable.RecId;
        newHistoryRecord.NetWeightFrom = lNDXItemNetWeightHistory.NetWeightTo;
        newHistoryRecord.NetWeightTo = _inventTable.NetWeight;

        if(_orig)
        {
            newHistoryRecord.NetWeightFrom = _orig.NetWeight;
        }

        newHistoryRecord.insert();
    }
}
